  const supabaseUrl=process.env.NEXT_PUBLIC_SUPABASE_URL||"",projectId=new URL(supabaseUrl).hostname.split(".")[0],anonKey=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY||process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY||"",endpoint="https://"+projectId+".storage.supabase.co/storage/v1/upload/resumable";
  const ok=await new Promise(resolve=>{try{const upload=new tus.Upload(file,{endpoint,retryDelays:[0,2000,5000,10000,20000,30000,45000,60000],headers:{authorization:"Bearer "+session.access_token,apikey:anonKey,"x-upsert":"true"},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,chunkSize:4*1024*1024,metadata:{bucketName:"media",objectName:path,contentType:file.type,cacheControl:"3600"},onError:error=>{console.error("TUS upload failed",error);resolve(false)},onProgress:(bytes,total)=>{setProgress(Math.max(2,Math.round((bytes/total)*84)))},onSuccess:()=>resolve(true)});upload.findPreviousUploads().then(previous=>{if(previous.length)upload.resumeFromPreviousUpload(previous[0]);upload.start()}).catch(error=>{console.error("TUS resume failed",error);resolve(false)})}catch(error){console.error("TUS init failed",error);resolve(false)}});
  if(!ok){await supabase.from("processing_jobs").update({status:"failed",error:"Resumable upload failed after automatic retries"}).eq("id",job.data.id);await supabase.from("project_sources").update({status:"failed"}).eq("id",src.data.id);await supabase.from("projects").update({status:"upload_failed"}).eq("id",project.id);setUploadMsg(navigator.onLine===false?"Your browser reports no internet connection. The resumable upload will work again when the connection returns.":"The video upload could not complete after automatic retries. Please retry; your upload uses 4 MB resumable chunks.");setBusy(false);return}
  setProgress(88);
  const assetUpdate=await supabase.from("media_assets").update({status:"uploaded"}).eq("id",asset.data.id);
  if(assetUpdate.error){setUploadMsg(assetUpdate.error.message);setBusy(false);return}
  const videoUpdate=await supabase.from("videos").update({status:"ready"}).eq("id",video.data.id);
  if(videoUpdate.error){setUploadMsg(videoUpdate.error.message);setBusy(false);return}
  await supabase.from("project_sources").update({status:"queued"}).eq("id",src.data.id);
  await supabase.from("projects").update({status:"processing"}).eq("id",project.id);
